    29  #define MAX_ITERATIONS 100
    30
    31  #include <stdlib.h>
    32  #include <string.h>
    33
    34  #include <openthread/instance.h>
    35  #include <openthread/ip6.h>
    36  #include <openthread/link.h>
    37  #include <openthread/ncp.h>
    38  #include <openthread/tasklet.h>
    39  #include <openthread/thread.h>
    40  #include <openthread/thread_ftd.h>
    41  #include <openthread/platform/uart.h>
    42
    43  #include "common/code_utils.hpp"
    44
    45  extern "C" void FuzzerPlatformInit(void);
    46  extern "C" void FuzzerPlatformProcess(otInstance *aInstance);
    47
    48  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    49  {
    50      const otPanId panId = 0xdead;
    51
    52      otInstance *instance = NULL;
    53      uint8_t *   buf      = NULL;
    54
    55      VerifyOrExit(size <= 65536);
    56
    57      FuzzerPlatformInit();
    58
    59      instance = otInstanceInitSingle();
    60      otNcpInit(instance);
    61      otLinkSetPanId(instance, panId);
    62      otIp6SetEnabled(instance, true);
    63      otThreadSetEnabled(instance, true);
    64      otThreadBecomeLeader(instance);
    65
    66      buf = static_cast<uint8_t *>(malloc(size));
    67
    68      memcpy(buf, data, size);
    69
    70      otPlatUartReceived(buf, (uint16_t)size);
    71
    72      for (int i = 0; i < MAX_ITERATIONS; i++)
    73      {
    74          while (otTaskletsArePending(instance))
    75          {
    76              otTaskletsProcess(instance);
    77          }
    78
    79          FuzzerPlatformProcess(instance);
    80      }
    81
    82  exit:
    83
    84      if (buf != NULL)
    85      {
    86          free(buf);
    87      }
    88
    89      if (instance != NULL)
    90      {
    91          otInstanceFinalize(instance);
    92      }
    93
    94      return 0;
    95  }
